import { readJsonFile } from "./readJson.js";

// Payload is generated by the bgelo repo and synced here with
// `python3 -m bgelo.site_sync`. Never hand-edit it; the full export contract
// is pinned in tests/data-invariants.test.js.
export function getEloData() {
  return readJsonFile("data/elo.json", {
    requiredKeys: [
      "meta", "corePlayers", "players", "series", "events",
      "sessions", "games", "headToHead", "playLog",
    ],
    nonEmpty: ["players", "events"],
    hint: "run `python3 -m bgelo.site_sync` in the bgelo repo",
  });
}
